// We use Verus for specification and verification
// To run this, put it in a file `min_scalar_type.rs` and run `rustc +nightly --edition=2018 --crate-type=lib min_scalar_type.rs --extern verus`
// (Assuming you have the Verus toolchain installed.)

verus! {

    // An enumeration of all supported NumPy scalar data types.
    #[verifier(publish)]
    spec enum NumpyDType {
        UInt8,
        UInt16,
        UInt32,
        UInt64,
        Int8,
        Int16,
        Int32,
        Int64,
        Float16,
        Float32,
        Float64,
        Complex64,
        Complex128,
    }

    // Compute 2^n as a mathematical (spec‐only) function.
    spec fn pow2(n: nat) -> nat
        decreases n
    {
        if n == 0 {
            1
        } else {
            2 * pow2(n - 1)
        }
    }

    // The bit‐width of each dtype.
    spec fn dtype_size(dt: NumpyDType) -> nat {
        match dt {
            NumpyDType::UInt8     => 8,
            NumpyDType::UInt16    => 16,
            NumpyDType::UInt32    => 32,
            NumpyDType::UInt64    => 64,
            NumpyDType::Int8      => 8,
            NumpyDType::Int16     => 16,
            NumpyDType::Int32     => 32,
            NumpyDType::Int64     => 64,
            NumpyDType::Float16   => 16,
            NumpyDType::Float32   => 32,
            NumpyDType::Float64   => 64,
            NumpyDType::Complex64  => 64,
            NumpyDType::Complex128 => 128,
        }
    }

    // The “kind order”: 0 = unsigned int, 1 = signed int, 2 = float, 3 = complex.
    spec fn dtype_kind_order(dt: NumpyDType) -> int {
        match dt {
            NumpyDType::UInt8  | NumpyDType::UInt16  | NumpyDType::UInt32  | NumpyDType::UInt64  => 0,
            NumpyDType::Int8   | NumpyDType::Int16   | NumpyDType::Int32   | NumpyDType::Int64   => 1,
            NumpyDType::Float16| NumpyDType::Float32 | NumpyDType::Float64                    => 2,
            NumpyDType::Complex64 | NumpyDType::Complex128                                => 3,
        }
    }

    // Predicate: can a given dtype represent the integer `v`?
    spec fn can_represent_value(dt: NumpyDType, v: int) -> bool {
        match dt {
            // Unsigned integers: 0 .. 2^bits − 1
            NumpyDType::UInt8  =>  0 <= v && v <= (pow2(8)  as int) - 1,
            NumpyDType::UInt16 =>  0 <= v && v <= (pow2(16) as int) - 1,
            NumpyDType::UInt32 =>  0 <= v && v <= (pow2(32) as int) - 1,
            NumpyDType::UInt64 =>  0 <= v && v <= (pow2(64) as int) - 1,

            // Signed integers: −2^(bits−1) .. 2^(bits−1) − 1
            NumpyDType::Int8   => -(pow2(7)  as int) <= v && v <= (pow2(7)  as int) - 1,
            NumpyDType::Int16  => -(pow2(15) as int) <= v && v <= (pow2(15) as int) - 1,
            NumpyDType::Int32  => -(pow2(31) as int) <= v && v <= (pow2(31) as int) - 1,
            NumpyDType::Int64  => -(pow2(63) as int) <= v && v <= (pow2(63) as int) - 1,

            // Floats and complex: for this problem, they represent every integer
            NumpyDType::Float16   |
            NumpyDType::Float32   |
            NumpyDType::Float64   |
            NumpyDType::Complex64 |
            NumpyDType::Complex128 => true,
        }
    }

    // The function we want to verify.
    // Input: a single signed 8‐bit integer (i8).
    // Output: the minimal dtype that can represent it, by the given rules.
    fn min_scalar_type(value: i8) -> (result: NumpyDType)
        ensures
            // 1) The chosen type can represent the value.
            can_represent_value(result, value as int),
        ensures
            // 2) No strictly smaller‐bit‐width type can represent the value.
            forall |dt: NumpyDType|
                dtype_size(dt) < dtype_size(result)
                ==> !can_represent_value(dt, value as int),
        ensures
            // 3) Among types of the same bit‐width that can represent the value,
            //    ours has minimal kind‐order.
            forall |dt: NumpyDType|
                dtype_size(dt) == dtype_size(result)
                && can_represent_value(dt, value as int)
                ==> dtype_kind_order(result) <= dtype_kind_order(dt)
    {
        if value >= 0 {
            // Non‐negative fits in UInt8 at 8 bits, and that's the most preferred (kind=0).
            result = NumpyDType::UInt8;
        } else {
            // Negative fits only in Int8 at 8 bits (UInt8 cannot), so that's minimal bit‐width.
            result = NumpyDType::Int8;
        }
        // The three ensures clauses are then verified automatically:
        //  - can_represent_value(UInt8, v) if v >= 0, or can_represent_value(Int8, v) if v < 0.
        //  - No dtype has bit‐width < 8 (by the problem statement, all are ≥ 8).
        //  - At bit‐width = 8, the only candidates are UInt8 (kind 0) and Int8 (kind 1).
        //    If v ≥ 0, both can represent, and UInt8 has smaller kind‐order.
        //    If v < 0, only Int8 can represent, so Int8 is trivially minimal among those.
    }

} // end verus!